def minMaxWaitingTime(demand, fuel):
    n = len(demand)

    # Prefix sums of demand: fuel consumed after serving the first i cars
    pre = [0] * (n + 1)
    for i in range(n):
        pre[i + 1] = pre[i] + demand[i]

    memo = {}

    # i  = next car, f0 = fuel left in dispenser 0
    # r0, r1 = how long until each dispenser is free, relative to the current time
    # Returns (max cars servable from here, min possible max-wait for that count)
    def solve(i, f0, r0, r1):
        if i == n:
            return (0, 0)
        key = (i, f0, r0, r1)
        if key in memo:
            return memo[key]

        # Fuel left in dispenser 1 follows from the total consumed so far
        f1 = fuel[1] - (pre[i] - (fuel[0] - f0))
        d = demand[i]
        best = (0, 0)

        for disp in (0, 1):
            if disp == 0:
                ok = f0 >= d
                wait = r0
                other = r1
            else:
                ok = f1 >= d
                wait = r1
                other = r0
            if not ok:
                continue
            # Time advances by 'wait' to the moment this car starts
            other = max(0, other - wait)
            if disp == 0:
                sub = solve(i + 1, f0 - d, d, other)
            else:
                sub = solve(i + 1, f0, other, d)
            cand = (sub[0] + 1, max(wait, sub[1]))
            # More cars served is better; ties broken by smaller max wait
            if cand[0] > best[0] or (cand[0] == best[0] and cand[1] < best[1]):
                best = cand

        memo[key] = best
        return best

    served, wait = solve(0, fuel[0], 0, 0)
    if served == 0:
        return -1
    return wait
